if(n>10){dist=Math.abs(a.x*b.y-a.y*b.x)/n;lx=Math.abs(b.y-a.y)>2?a.x+(b.x-a.x)*(-a.y/(b.y-a.y)):b.x}else{lx=b.x;dist=Math.hypot(b.x,b.y)}
