const path=k=>{g.beginPath();g.moveTo(pts[0].x+nx[0]*k,pts[0].y+ny[0]*k);for(let i=1;i<n;i++)g.lineTo(pts[i].x+nx[i]*k,pts[i].y+ny[i]*k);for(let i=n-1;i>=0;i--)g.lineTo(pts[i].x-nx[i]*k,pts[i].y-ny[i]*k);g.closePath()};
const fev=typeof feverT!=='undefined'&&feverT>0,glow=fev?'hsla('+((time*240)%360|0)+',100%,62%,.42)':'rgba(255,170,60,.38)',mid=fev?'hsla('+(((time*240)+40)%360|0)+',100%,78%,.9)':'rgba(255,226,140,.88)';
g.save();g.lineJoin='round';g.shadowColor=fev?'hsla('+((time*240)%360|0)+',100%,60%,.9)':'rgba(255,190,70,.9)';g.shadowBlur=11;g.fillStyle=glow;path(1.9);g.fill();g.shadowBlur=0;g.fillStyle=mid;path(1.1);g.fill();g.fillStyle='#fff';path(.5);g.fill();
