function swipeChar(left){const want=left?2:1,other=left?1:2,ok=c=>!chLock[c]&&chStam[c]>=.5;let t=-1;if(curChar===want)t=0;else if(ok(want))t=want;else if(curChar!==other&&ok(other))t=other;else if(curChar!==0)t=0;if(t<0){tkWarnT=.6;return}swPrev=curChar;swDir=left?1:-1;swT=SW_DUR;curChar=t;lay();wv-=240}
