function bgmPluck(ctx,out,t,m,vol){const f=bgmHz(m),o=ctx.createOscillator(),o2=ctx.createOscillator(),g=ctx.createGain(),g2=ctx.createGain();o.type='triangle';o2.type='sine';o.frequency.setValueAtTime(f,t);o2.frequency.setValueAtTime(f*2,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.006);g.gain.exponentialRampToValueAtTime(.0001,t+1.3);g2.gain.setValueAtTime(vol*.35,t);g2.gain.exponentialRampToValueAtTime(.0001,t+.5);o.connect(g);o2.connect(g2);g.connect(out);g2.connect(out);o.start(t);o2.start(t);o.stop(t+1.35);o2.stop(t+.55)}
