function startTitleBgm(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=audioCtx||new AC();const ctx=audioCtx;if(ctx.state==='suspended')ctx.resume();if(BGM.playing)return;if(!BGM.gain){BGM.gain=ctx.createGain();BGM.gain.connect(getAudioOutput(ctx))}BGM.gain.gain.cancelScheduledValues(ctx.currentTime);BGM.gain.gain.setValueAtTime(.0001,ctx.currentTime);BGM.gain.gain.linearRampToValueAtTime(1,ctx.currentTime+1.8);BGM.playing=true;BGM.step=0;BGM.next=ctx.currentTime+.15;clearInterval(BGM.timer);BGM.timer=setInterval(bgmSchedule,120);bgmSchedule()}catch(_){}}
