function kickAudio(e){try{if(e&&e.target&&e.target.closest&&e.target.closest('#bgm-toggle'))return;if(state==='title'&&!BGM.playing)startTitleBgm();else if(BGM.playing&&audioCtx&&audioCtx.state!=='running')audioCtx.resume()}catch(_){}}
