/* ===== ゲーム中BGM（中華風ペンタ × ロック調エレクトロ・アップテンポ） ===== */
const GB={timer:null,watch:null,playing:false,next:0,step:0,gain:null,bpm:144,noise:null,dist:null};
const GB_P=[64,67,69,71,74,76,79,81],GB_ROOT=[40,43,45,38,40,43,45,38];
const GB_LEAD=[[4,-1,4,-1,3,-1,2,-1,3,-1,4,-1,5,-1,4,3],[2,-1,2,-1,1,-1,0,-1,1,-1,2,-1,3,-1,2,1],[5,-1,5,-1,4,-1,3,-1,4,-1,5,-1,6,-1,5,4],[3,-1,3,2,3,-1,4,-1,5,-1,4,3,2,-1,1,-1],[4,-1,4,-1,3,-1,2,-1,3,-1,4,-1,5,-1,4,3],[2,-1,2,-1,1,-1,0,-1,1,-1,2,-1,3,-1,2,1],[5,-1,5,-1,4,-1,3,-1,4,-1,5,-1,6,-1,5,4],[7,-1,6,-1,5,-1,4,-1,3,-1,2,-1,1,-1,0,-1]];
function gbCtxInit(ctx){if(!GB.noise){const len=ctx.sampleRate,b=ctx.createBuffer(1,len,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<len;i++)d[i]=Math.random()*2-1;GB.noise=b}if(!GB.dist){const n=2048,c=new Float32Array(n),k=40;for(let i=0;i<n;i++){const x=i*2/n-1;c[i]=(1+k)*x/(1+k*Math.abs(x))}GB.dist=c}}
function gbKick(ctx,out,t){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(170,t);o.frequency.exponentialRampToValueAtTime(42,t+.13);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.42,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.connect(g);g.connect(out);o.start(t);o.stop(t+.22)}
function gbNoise(ctx,out,t,type,freq,q,vol,dur){const src=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();src.buffer=GB.noise;f.type=type;f.frequency.setValueAtTime(freq,t);f.Q.setValueAtTime(q,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.003);g.gain.exponentialRampToValueAtTime(.0001,t+dur);src.connect(f);f.connect(g);g.connect(out);src.start(t,Math.random()*.5);src.stop(t+dur+.02)}
function gbSnare(ctx,out,t){gbNoise(ctx,out,t,'bandpass',2200,.8,.2,.16);const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(240,t);o.frequency.exponentialRampToValueAtTime(130,t+.09);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.16,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+.11);o.connect(g);g.connect(out);o.start(t);o.stop(t+.12)}
function gbBass(ctx,out,t,m,vol,dur){const o=ctx.createOscillator(),lp=ctx.createBiquadFilter(),g=ctx.createGain();o.type='sawtooth';o.frequency.setValueAtTime(bgmHz(m),t);lp.type='lowpass';lp.frequency.setValueAtTime(900,t);lp.frequency.exponentialRampToValueAtTime(260,t+dur);lp.Q.setValueAtTime(3,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.008);g.gain.setValueAtTime(vol,t+dur*.6);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(lp);lp.connect(g);g.connect(out);o.start(t);o.stop(t+dur+.02)}
function gbStab(ctx,out,t,root,dur,vol){const ws=ctx.createWaveShaper(),lp=ctx.createBiquadFilter(),g=ctx.createGain();ws.curve=GB.dist;lp.type='lowpass';lp.frequency.setValueAtTime(2600,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.006);g.gain.setValueAtTime(vol,t+dur*.5);g.gain.exponentialRampToValueAtTime(.0001,t+dur);for(const[m,dt]of[[root+12,-6],[root+12,7],[root+19,-4],[root+19,5]]){const o=ctx.createOscillator();o.type='sawtooth';o.frequency.setValueAtTime(bgmHz(m),t);o.detune.setValueAtTime(dt,t);o.connect(ws);o.start(t);o.stop(t+dur+.03)}ws.connect(lp);lp.connect(g);g.connect(out)}
