if(pos===4||pos===12||(fill&&pos>=12))gbSnare(ctx,out,t);
if(pos%2===0)gbNoise(ctx,out,t,'highpass',7500,.7,pos%4===0?.06:.04,.045);else if(pos===15&&!fill)gbNoise(ctx,out,t,'highpass',6500,.7,.035,.12);
