function startGameBgm(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=audioCtx||new AC();const ctx=audioCtx;if(ctx.state==='suspended')ctx.resume();if(GB.playing)return;gbCtxInit(ctx);GB.gain=ctx.createGain();GB.gain.connect(getAudioOutput(ctx));GB.gain.gain.setValueAtTime(.0001,ctx.currentTime);GB.gain.gain.linearRampToValueAtTime(.6,ctx.currentTime+.25);GB.playing=true;GB.next=ctx.currentTime+.05;clearInterval(GB.timer);GB.timer=setInterval(gbSchedule,60);gbSchedule()}catch(_){}}
