const RB={timer:null,watch:null,playing:false,next:0,step:0,gain:null,tier:1};
/* ★1：しっとり穏やか（Am・スロー） */
const RB1_ROOT=[45,41,43,45,45,41,43,40];
const RB1_CH=[[57,60,64,69],[60,64,65,69],[62,67,69,74],[57,60,64,69],[57,60,64,69],[60,64,65,69],[62,67,69,74],[59,64,67,71]];
