/* ★2：軽快でごきげん（D・ミドルテンポ） */
const RB2_ROOT=[50,45,47,43,50,45,47,45];
const RB2_CH={D:[62,66,69,74],A:[64,69,73,76],B:[62,66,71,74],G:[62,67,71,74]};
