const RB3_ROOT=[48,43,45,41,48,43,41,43],RB3_P=[67,69,72,74,76,79,81,84];
const RB3_LEAD=[[5,-1,5,-1,6,-1,5,-1,4,-1,-1,-1,2,-1,4,-1],[3,-1,3,-1,5,-1,6,-1,5,-1,-1,-1,3,-1,-1,-1],[6,-1,6,-1,5,-1,4,-1,2,-1,4,-1,5,-1,-1,-1],[7,-1,6,-1,5,-1,4,-1,6,-1,-1,-1,-1,-1,-1,-1],[5,-1,5,-1,7,-1,7,-1,6,-1,5,-1,4,-1,5,-1],[6,-1,6,-1,5,-1,3,-1,5,-1,6,-1,5,-1,3,-1],[6,-1,5,-1,4,-1,2,-1,4,-1,5,-1,6,-1,-1,-1],[5,-1,6,-1,7,-1,-1,-1,7,-1,-1,-1,-1,-1,-1,-1]];
function rbT3(ctx,out,t,bar,pos,u,st){const root=RB3_ROOT[bar],fill=bar===7;if(st===0)gbNoise(ctx,out,t,'highpass',3500,.6,.12,1.2);if(pos%4===0||(fill&&pos===14))gbKick(ctx,out,t);if(pos===4||pos===12||(fill&&pos>=12))gbSnare(ctx,out,t);if(pos%2===0)gbNoise(ctx,out,t,'highpass',7500,.7,pos%4===0?.05:.035,pos%4===2?.1:.045);if(pos%2===0)gbBass(ctx,out,t,(pos===6||pos===14)?root+12:root,.1,u*1.8);if(pos===0||pos===6||pos===10)gbStab(ctx,out,t,root,u*(pos===0?3.2:1.7),.035);if(pos===0)bgmPluck(ctx,out,t,root+36,.03);const li=RB3_LEAD[bar][pos];if(li>=0)gbLead(ctx,out,t,RB3_P[li],u*1.9,.036)}
