function startResultBgm(stars){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=audioCtx||new AC();const ctx=audioCtx;if(ctx.state==='suspended')ctx.resume();if(RB.playing)stopResultBgm();stopTitleBgm();gbCtxInit(ctx);const tier=stars>=3?3:stars===2?2:1,c=RB_CFG[tier];RB.tier=tier;RB.gain=ctx.createGain();RB.gain.connect(getAudioOutput(ctx));RB.gain.gain.setValueAtTime(.0001,ctx.currentTime);RB.gain.gain.linearRampToValueAtTime(c.vol,ctx.currentTime+.4);RB.playing=true;RB.step=0;RB.next=ctx.currentTime+.1;clearInterval(RB.timer);RB.timer=setInterval(rbSchedule,60);rbSchedule()}catch(_){}}
