/* 禁止ワード判定（リストは別ファイル ng-words.js の window.NG_WORDS）。表記ゆれをそろえて部分一致で調べる */
function normNgText(s){return String(s==null?'':s).normalize('NFKC').toLowerCase().replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60)).replace(/[\s._\-*+~・、。!?'"`^|\/\\()\[\]「」【】]/g,'')}
let ngCache=null;
function ngBuild(){const list=k=>Array.isArray(window[k])?window[k]:[],escRe=t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
return{sub:[].concat(list('NG_WORDS'),list('NG_WORDS_JA')).map(normNgText).filter(Boolean),
allow:list('NG_WORDS_ALLOW').map(normNgText).filter(Boolean),
word:list('NG_WORDS_WORD').map(w=>String(w).normalize('NFKC').toLowerCase().trim()).filter(Boolean).map(w=>new RegExp('(^|[^a-z0-9])'+w.split(/\s+/).map(escRe).join('[^a-z0-9]+')+'(?![a-z0-9])'))}}
function isNgName(name){const c=ngCache||(ngCache=ngBuild());let n=normNgText(name);c.allow.forEach(a=>{n=n.split(a).join('')});if(c.sub.some(k=>n.indexOf(k)!==-1))return true;const t=String(name==null?'':name).normalize('NFKC').toLowerCase();return c.word.some(re=>re.test(t))}
