function renderRanking(){const list=document.getElementById('ranking-list');if(!list)return;const records=readRanking().slice(0,3);list.innerHTML=records.length?records.map((r,i)=>`<li><span class="place">${i+1}</span><span class="entry-name">${escapeHtml(r.name||'無名の料理人')}</span><span class="entry-score">${r.score}点</span><span class="entry-stars">${'★'.repeat(Math.max(1,Math.min(3,r.stars||1)))}</span><span class="entry-title">${escapeHtml(displayTitle(r))}</span></li>`).join(''):'<li class="ranking-empty">まだ記録がありません。最初の一位を目指そう！</li>'}
