let shareImagePromise=null,shareFileReady=null;
function prepareShareImage(d){shareFileReady=null;const go=async()=>{try{if(scoreChefImg.decode)await scoreChefImg.decode().catch(()=>{});const blob=await renderShareImage(d);if(blob)shareFileReady=new File([blob],'chuka-hanten-r-score.png',{type:'image/png'})}catch(_){shareFileReady=null}return shareFileReady};shareImagePromise=(document.fonts&&document.fonts.ready?document.fonts.ready.then(go,go):go())}
/* スマホ：画像＋文面を共有メニューへ。ボタンを押した直後（ユーザー操作の中）で共有を呼ぶため、画像は事前に作っておく */
function shareToX(resultScore,resultTitle,resultStars,resultMessage){const message=buildShareMessage(resultScore,resultTitle,resultStars,resultMessage);
const fallback=()=>openTweetIntent(message);
if(!(isMobileDevice()&&navigator.share)){fallback();return}
const doShare=file=>{const data={files:[file],text:message};if(navigator.canShare&&!navigator.canShare(data)){fallback();return}navigator.share(data).catch(err=>{if(!err||err.name!=='AbortError')fallback()})};
if(shareFileReady){try{doShare(shareFileReady)}catch(_){fallback()}return}
(shareImagePromise||Promise.resolve(null)).then(file=>{if(file)doShare(file);else fallback()},fallback)}
function shareSiteToX(){const message='中華飯店Rをプレイ！';const url='https://twitter.com/intent/tweet?text='+encodeURIComponent(message)+'&url='+encodeURIComponent(SHARE_SITE_URL);window.open(url,'_blank','noopener,noreferrer')}
function showFailure(){document.getElementById('pause-toggle').classList.remove('active');state='result';window.cutResult={score,counts:{...counts},poison:counts.poison,bomb:counts.bomb,quality:qN?+(qSum/qN).toFixed(2):0,perfect:perfN,maxCombo,bombEnded:true};const e=document.getElementById('res');e.classList.remove('hide');e.innerHTML=`<div class="failure-screen"><img src="${curChar===2?NC_IMG.bad.src:'img/failure-chef.webp'}" alt="${curChar===2?'失敗して慌てるマリーナ':'失敗して慌てる料理人'}"><h2>調理失敗</h2><p>爆弾キノコに触れてしまった……！<br>次は危険な食材を見送ろう。</p><div class="final-action"><button id="again">もういちど挑戦</button><button id="to-title" class="secondary-button">タイトルへ戻る</button></div></div>`;document.getElementById('again').onclick=()=>{e.classList.add('hide');reset();countdownT=3.7;state='countdown';document.getElementById('pause-toggle').classList.add('active')};document.getElementById('to-title').onclick=()=>backToTitle(true)}
