function readDishBook(){try{const v=JSON.parse(localStorage.getItem(DISH_KEY)||'{}');return(v&&typeof v==='object')?v:{}}catch(_){return {}}}
function writeDishBook(b){try{localStorage.setItem(DISH_KEY,JSON.stringify(b))}catch(_){}}
function pickDish(cn){const c={};for(const k of NORMAL_KEYS.concat('poison'))c[k]=(cn&&cn[k])||0;for(const d of DISHES)if(d.t(c))return d;return DISHES[DISHES.length-1]}
function pickDishes(cn){const c={};for(const k of NORMAL_KEYS.concat('poison'))c[k]=(cn&&cn[k])||0;const hit=DISHES.filter(d=>d.id!=='empty'&&d.t(c));return hit.length?hit:[DISHES[DISHES.length-1]]}
/* 同じプレイ中に実績時点で登録済みの料理は、回数を増やさず最高点だけ更新する */
window.__runRec=window.__runRec||new Set();
function recordDish(d,score){const b=readDishBook(),prev=b[d.id],again=window.__runRec.has(d.id),isNew=!prev;window.__runRec.add(d.id);b[d.id]={n:(prev?prev.n:0)+(again?0:1),best:Math.max(prev?prev.best:0,score)};writeDishBook(b);return again?false:isNew}
function dishGrade(stars){return stars>=3?'極上':stars===2?'上出来':'家庭の味'}
function dishIngredients(cn){return NORMAL_KEYS.concat('poison').filter(k=>cn&&cn[k]>0).map(k=>`<span class="dish-chip">${ING_EMOJI[k]} ${escapeHtml(TY[k].n)} ×${cn[k]}</span>`).join('')}
function dishCardMarkup(d){const dish=d.dish,total=Object.keys(readDishBook()).filter(id=>DISHES.some(x=>x.id===id)).length;return `<div class="dish-reveal"><div class="dish-stage q${d.stars}">${dishArt(dish,d.stars,false)}</div><div class="dish-rarity">${dishTrophy(dish.r)}</div>${d.dishNew?'<div class="dish-new">NEW! 図鑑に登録</div>':''}<h2 class="dish-name">${dishGrade(d.stars)}・${escapeHtml(dish.n)}</h2><p class="dish-desc">${escapeHtml(dish.d)}</p><div class="dish-chips">${dishIngredients(d.counts)||'<span class="dish-chip">食材なし</span>'}</div>${(d.extra&&d.extra.length)?`<div class="dish-also"><div class="dish-also-h">同時達成！ ほか${d.extra.length}品も図鑑に登録</div><div class="dish-also-list">${d.extra.slice(0,8).map(x=>`<span class="dish-also-chip${x.isNew?' new':''}">${dishTrophy(x.d.r)} ${escapeHtml(x.d.n)}${x.isNew?' <b>NEW</b>':''}</span>`).join('')}${d.extra.length>8?`<span class="dish-also-chip">…ほか${d.extra.length-8}品</span>`:''}</div></div>`:''}<div class="dish-book-count">料理図鑑 ${total} / ${DISHES.length}</div></div>`}
function renderDishBook(){const el=document.getElementById('dish-grid');if(!el)return;const b=readDishBook(),got=DISHES.filter(d=>b[d.id]).length;document.getElementById('dish-progress').textContent=got+' / '+DISHES.length;el.innerHTML=DISHES.map((d,i)=>({d,i})).sort((x,y)=>x.d.r-y.d.r||x.i-y.i).map(o=>o.d).map(d=>{const r=b[d.id];return r?`<div class="dish-cell got" data-dish="${d.id}" role="button" tabindex="0"><span class="dc-art">${dishArt(d,0,true)}</span><small>${dishTrophy(d.r)}</small><b>${escapeHtml(d.n)}</b></div>`:`<div class="dish-cell" data-dish="${d.id}" role="button" tabindex="0"><span class="dc-emoji">❓</span><small>${dishTrophy(d.r)}</small><b>？？？</b><small>条件：${escapeHtml(d.h)}</small></div>`}).join('')}
function showResult(){if(bombEnd){showFailure();return}document.getElementById('pause-toggle').classList.remove('active');state='result';const q=qN?qSum/qN:0,safe=counts.poison===0&&dangerAvoided===dangerSpawned;let stars=1;
/* 称号は得点だけで決まる（称号ポイントは廃止） */
const titles=TITLE_RANKS;
let title=titles[0];for(const row of titles)if(score>=row[0])title=row;const titleRank=titles.indexOf(title)+1;markTitleEarned(title[1]);
/* 星判定：★2=1.5万点以上／★3=称号ランク17以上は自動／それ未満は★2条件＋BADなし＋（称号ランク14以上では毒キノコ・爆弾に一度も触れない） */
if(score>=STAR2_SCORE){stars=2;if(titleRank>=STAR3_AUTO_RANK||(badN===0&&(titleRank<STAR3_SAFE_RANK||safe)))stars=3}
window.cutResult={score,counts:{...counts},poison:counts.poison,bomb:counts.bomb,quality:+q.toFixed(2),perfect:perfN,maxCombo,dangerAvoided,dangerSpawned,stars,titleRank,titleName:title[1],titleMessage:title[2],bombEnded:false};saveRanking({score,stars,name:playerName,title:title[1],titleRank});submitOnlineScore({score,stars,name:playerName,title:title[1]});
const hits=pickDishes(counts),dish=hits[0],dishNew=recordDish(dish,score),extra=hits.slice(1).map(x=>({d:x,isNew:recordDish(x,score)}));finalData={score,stars,title:title[1],message:title[2],maxCombo,dish,dishNew,extra,counts:{...counts}};if(stars===3)playRareSound();startResultBgm(stars);renderFinalStep(1)}
/* リザルトの得点：桁数・画面幅に関わらず、枠内に収まるまでフォントを縮める（見切れ防止） */
function fitScoreValues(){document.querySelectorAll('#res .score-value').forEach(el=>{try{const box=el.closest('.scene-content')||el.parentElement;if(!box)return;el.style.fontSize='';el.style.maxWidth='none';const cs=getComputedStyle(box),avail=(box.clientWidth-(parseFloat(cs.paddingLeft)||0)-(parseFloat(cs.paddingRight)||0))*.9,base=parseFloat(getComputedStyle(el).fontSize)||64,w=el.offsetWidth;if(w>avail&&w>0)el.style.fontSize=Math.max(14,Math.floor(base*avail/w*10)/10)+'px';el.style.maxWidth=''}catch(_){}})}
window.addEventListener('resize',fitScoreValues);window.addEventListener('orientationchange',()=>setTimeout(fitScoreValues,150));
function renderFinalStep(step){clearTimeout(finalStepTimer);const d=finalData,e=document.getElementById('res');if(!d)return;e.classList.remove('hide');if(step===1)playCookingSizzle();const starMarkup=[0,1,2].map(i=>`<span class="${i<d.stars?'lit':''}">★</span>`).join('');const grouped=[];for(const item of cutHistory){let row=grouped.find(x=>x.name===item.name);if(!row){row={name:item.name,points:[]};grouped.push(row)}row.points.push(item.points)}const detailMarkup=`<section class="cut-history"><h3>切った食材</h3>${grouped.length?`<ul>${grouped.map(row=>`<li><span class="cut-history-name">${escapeHtml(row.name)} <small>×${row.points.length}</small></span></li>`).join('')}</ul>`:'<p>食材を切れませんでした</p>'}<p class="cut-history-combo">最高コンボ：${d.maxCombo||0}回</p></section>`;const viewStep=step;let body='';
if(step===1)body=`<div class="scene-art chef-art"><img src="${TC}" alt="料理人のカットイン"></div><h2>鍋振りフィニッシュ！</h2><p>最後のひと振りで、料理が完成。</p>`;
if(step===2)body=dishCardMarkup(d);
if(step===3)prepareShareImage(d);if(step===3)body=`<div class="score-label">今回の得点</div><div class="score-value">${d.score}<small>点</small></div><div class="title-ribbon">称号「${d.title}」</div><p class="title-message">${d.message}</p><div class="stars compact-stars">${starMarkup}</div><div class="online-rank-line" id="online-rank-line">${onlineRankText()}</div><div class="final-actions"><button id="again">もういちど挑戦</button><button id="share-result" class="share-button">𝕏でシェア</button><button id="to-title" class="secondary-button">タイトルへ戻る</button></div>${detailMarkup}`;
e.innerHTML=`<section class="final-scene scene-${step} rank-${d.stars}">${step===3?'<img class="score-chef" alt="" aria-hidden="true">':''}<div class="scene-content">${body}</div>${(step===1||step===2)?`<button class="scene-next" id="scene-next">次へ <span>›</span></button>`:''}<div class="scene-progress">${[1,3].map(i=>`<i class="${i<=viewStep?'active':''}"></i>`).join('')}</div></section>`;
{const ci=e.querySelector('.score-chef');if(ci)ci.src=(d.stars===1?'img/score-chef-1star.webp':d.stars===3?SCORE_CHEF3_SRC:SCORE_CHEF_SRC)}fitScoreValues();if(document.fonts&&document.fonts.ready)document.fonts.ready.then(fitScoreValues);
if(step===1){const sc=e.querySelector('.final-scene'),t0=performance.now();sc.onclick=ev=>{if(ev.target.closest('#scene-next')||performance.now()-t0<350)return;const r=sc.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width,y=(ev.clientY-r.top)/r.height;if(x>.2&&x<.8&&y>.25&&y<.75)renderFinalStep(3)};document.getElementById('scene-next').onclick=()=>renderFinalStep(3);finalStepTimer=setTimeout(()=>renderFinalStep(3),4200)}else if(step===2){document.getElementById('scene-next').onclick=()=>renderFinalStep(3);finalStepTimer=setTimeout(()=>renderFinalStep(3),9000)}else{document.getElementById('again').onclick=()=>{e.classList.add('hide');reset();countdownT=3.7;state='countdown';document.getElementById('pause-toggle').classList.add('active')};document.getElementById('to-title').onclick=backToTitle;document.getElementById('share-result').onclick=()=>shareToX(d.score,d.title,d.stars,d.message)}}
